begin;
do $curate$ declare r jsonb; bid uuid; applied jsonb; begin
for r in select value from jsonb_array_elements('[{"name":"Junk Geni","city":"Tracy","phone":"(209) 833-3265","website":"https://www.junkgeni.com/","source_url":"https://www.junkgeni.com/","key":"junkgeni.com","areas":["Mountain House","Tracy","Lathrop","Manteca"],"tags":["junk removal","appliance removal","garage cleanouts","yard waste removal"],"description":"Tracy-based provider advertising junk removal, furniture and appliance hauling, garage and shed cleanouts, hot-tub removal and yard-debris removal. Its website explicitly names Mountain House, Tracy, Lathrop and Manteca. Confirm accepted materials, access, disposal charges, quote and pickup dates directly. No public visitor street address is established here.","note":"Website information checked November 19, 2026. Desk check only: no owner contact, credential/insurance/workmanship/rating/price or appointment availability confirmation. No photos, portfolios, reviews or promotional claims reused. Fresh HTTP200: identity, public2098333265 phone, advertised hauling/cleanout services and all four named service cities. Normal published hours are not Thanksgiving or holiday availability."},{"name":"LUNKERS Hauling","city":"Manteca","phone":"(209) 284-3382","website":"https://www.lunkershauling.com/","source_url":"https://www.lunkershauling.com/services","key":"lunkershauling.com","areas":["Mountain House","Tracy","Lathrop","Manteca"],"tags":["junk removal","appliance removal","property cleanouts","yard waste removal"],"description":"Manteca-based provider advertising furniture and appliance removal, yard-debris hauling and residential, property and commercial cleanouts. Its official service list names Mountain House, Tracy, Lathrop and Manteca. Published hours differ between pages; confirm hours, accepted materials, access, disposal terms, quote and pickup dates directly.","note":"Website information checked November 19, 2026. Desk check only: no owner contact, credential/insurance/workmanship/rating/price or appointment availability confirmation. No photos, portfolios, reviews or promotional claims reused. Fresh HTTP200 homepage and services page: public2092843382 phone, stated Manteca base, exact removal/cleanout services and four named service cities. Homepage says Mon-Sat9AM-6PM; services page says Mon-Sat8AM-6PM/Sun by appointment. Hours left unconfirmed; same-day, disposal/recycling and price claims not adopted. Sources: https://www.lunkershauling.com/ https://www.lunkershauling.com/services"},{"name":"One Strong Man Junk Removal & Moving Services","city":"Tracy","phone":"(209) 650-3977","website":"https://onestrongman209.com/","source_url":"https://onestrongman209.com/","key":"onestrongman209.com","areas":["Mountain House","Tracy","Lathrop","Manteca"],"tags":["junk removal","moving labor","garage cleanouts","yard waste removal"],"description":"Tracy-based provider advertising junk, furniture and appliance removal, garage cleanouts, yard cleanups and moving labor. Its official website names Mountain House, Tracy, Lathrop and Manteca. Moving labor is not a confirmed full-service transport arrangement. Confirm job scope, accepted materials, required credentials, quote and dates directly.","note":"Website information checked November 19, 2026. Desk check only: no owner contact, credential/insurance/workmanship/rating/price or appointment availability confirmation. No photos, portfolios, reviews or promotional claims reused. Fresh HTTP200 homepage and official Lathrop page: public2096503977 phone, Tracy identity/base, removal/cleanout/moving-labor descriptions and explicit four-city coverage. No visitor street address inferred; no discount, same-day, moving-license, transport or disposal guarantees adopted. Sources: https://onestrongman209.com/ https://onestrongman209.com/lathrop-ca/"},{"name":"Armstrong Cleaning & Restoration","city":"Service area only","phone":"(209) 879-9553","website":"https://armstrongcleaningandrestoration.com/","source_url":"https://armstrongcleaningandrestoration.com/dryer-vent-cleaning","key":"armstrongcleaningandrestoration.com","areas":["Mountain House","Tracy"],"tags":["dryer vent cleaning"],"description":"Advertises dryer-vent cleaning specifically for Mountain House and Tracy. Call to confirm the vent arrangement, property eligibility, exact cleaning scope, quote and appointment dates. A dated limited-time promotion is not adopted as current pricing. No visitor office is established by this check.","note":"Website information checked November 19, 2026. Desk check only: no owner contact, credential/insurance/workmanship/rating/price or appointment availability confirmation. No photos, portfolios, reviews or promotional claims reused. Fresh HTTP200 homepage and dryer-vent page: identity, public2098799553 phone and service-specific Mountain House/Tracy heading. Footer names other cities, but additional dryer-service coverage is not inferred. Limited-time price and safety/performance guarantees omitted. Sources: https://armstrongcleaningandrestoration.com/ https://armstrongcleaningandrestoration.com/dryer-vent-cleaning"},{"name":"Tri Valley HVAC LLC — AireServ Bay Area","city":"Pleasanton","phone":"(925) 268-9989","website":"https://aireservbayarea.com/","source_url":"https://aireservbayarea.com/","key":"aireservbayarea.com","areas":["Mountain House","Lathrop","Manteca"],"tags":["dryer vent cleaning","air duct cleaning","heating and air conditioning"],"description":"Pleasanton-based provider whose website advertises residential and commercial heating/air-conditioning work, air-duct cleaning and dryer-vent cleaning. Its coverage list explicitly names Mountain House, Lathrop and Manteca. Tracy coverage is unconfirmed because that list spells the city as Tracey. Confirm your address, specific service, quote and appointment dates directly.","note":"Website information checked November 19, 2026. Desk check only: no owner contact, credential/insurance/workmanship/rating/price or appointment availability confirmation. No photos, portfolios, reviews or promotional claims reused. Fresh HTTP200 landing page: self-identified business name, public9252689989 phone, Pleasanton mailing location, HVAC/duct/dryer services and explicit Mountain House/Lathrop/Manteca coverage. No walk-in office, franchise relationship or license status independently confirmed. Tracy coverage held because the page says Tracey; linked franchise page does not resolve exact four-city scope. Sources: https://aireservbayarea.com/ https://www.aireserv.com/pleasanton/"}]'::jsonb) loop
 if exists(select 1 from public.businesses where lower(name)=lower(r->>'name') or website ilike '%'||(r->>'key')||'%' or right(regexp_replace(coalesce(phone,''),'[^0-9]','','g'),10)=right(regexp_replace(r->>'phone','[^0-9]','','g'),10)) then raise exception 'Duplicate requires individual review: %',r->>'name';end if;
 insert into public.businesses(name,category,city,address,phone,website,description,status,verified,claimed,rating,review_count,needs_review,source,source_url,verification_source,verified_at) values(r->>'name','Home Services',r->>'city',null,r->>'phone',r->>'website',r->>'description','approved',true,false,null,0,false,'editorial_first_party',r->>'source_url','first_party_website_desk_check',now()) returning id into bid;
 insert into public.listing_checks(business_id,source_url,checked_fields,service_areas,service_tags,scope_note) values(bid,r->>'source_url',array['identity','public phone','website','advertised services','explicit service cities','scope and limitations'],array(select jsonb_array_elements_text(r->'areas')),array(select jsonb_array_elements_text(r->'tags')),r->>'note');
 select to_jsonb(b) into applied from public.businesses b where id=bid;
 insert into directory_private.listing_corrections(business_id,previous_values,applied_values,reason,source_reference) values(bid,'{}'::jsonb,applied||jsonb_build_object('service_areas',r->'areas','service_tags',r->'tags','scope_note',r->>'note'),'CORE-01 individually first-party checked service expansion; no seed publication',r->>'source_url');
end loop;end $curate$;
commit;

begin;
do $search_copy$ declare r jsonb; bid uuid; previous jsonb; applied jsonb; changed integer; begin
for r in select value from jsonb_array_elements('[{"name":"Junk Geni","website":"https://www.junkgeni.com/","old":"Tracy-based provider advertising junk removal, furniture and appliance hauling, garage and shed cleanouts, hot-tub removal and yard-debris removal. Its website explicitly names Mountain House, Tracy, Lathrop and Manteca. Confirm accepted materials, access, disposal charges, quote and pickup dates directly. No public visitor street address is established here.","next":"Tracy-based provider advertising junk removal, furniture and appliance hauling, garage and shed cleanouts, hot-tub removal and yard-debris removal. Its website explicitly names Mountain House, Tracy, Lathrop and Manteca. Confirm accepted materials, access, disposal charges, quote and pickup dates directly. No public visitor street address is established here.","source":"https://www.junkgeni.com/"},{"name":"LUNKERS Hauling","website":"https://www.lunkershauling.com/","old":"Manteca-based provider advertising furniture and appliance removal, yard-debris hauling and residential, property and commercial cleanouts. Its official service list names Mountain House, Tracy, Lathrop and Manteca. Published hours differ between pages; confirm hours, accepted materials, access, disposal terms, quote and pickup dates directly.","next":"Manteca-based provider advertising junk removal, furniture and appliance removal, yard-debris hauling and residential, property and commercial cleanouts. Its official service list names Mountain House, Tracy, Lathrop and Manteca. Published hours differ between pages; confirm hours, accepted materials, access, disposal terms, quote and pickup dates directly.","source":"https://www.lunkershauling.com/services"},{"name":"Armstrong Cleaning & Restoration","website":"https://armstrongcleaningandrestoration.com/","old":"Advertises dryer-vent cleaning specifically for Mountain House and Tracy. Call to confirm the vent arrangement, property eligibility, exact cleaning scope, quote and appointment dates. A dated limited-time promotion is not adopted as current pricing. No visitor office is established by this check.","next":"Advertises dryer vent cleaning specifically for Mountain House and Tracy. Call to confirm the vent arrangement, property eligibility, exact cleaning scope, quote and appointment dates. A dated limited-time promotion is not adopted as current pricing. No visitor office is established by this check.","source":"https://armstrongcleaningandrestoration.com/dryer-vent-cleaning"},{"name":"Tri Valley HVAC LLC — AireServ Bay Area","website":"https://aireservbayarea.com/","old":"Pleasanton-based provider whose website advertises residential and commercial heating/air-conditioning work, air-duct cleaning and dryer-vent cleaning. Its coverage list explicitly names Mountain House, Lathrop and Manteca. Tracy coverage is unconfirmed because that list spells the city as Tracey. Confirm your address, specific service, quote and appointment dates directly.","next":"Pleasanton-based provider whose website advertises residential and commercial heating/air-conditioning work, air-duct cleaning and dryer vent cleaning. Its coverage list explicitly names Mountain House, Lathrop and Manteca. Tracy coverage is unconfirmed because that list spells the city as Tracey. Confirm your address, specific service, quote and appointment dates directly.","source":"https://aireservbayarea.com/"}]'::jsonb) loop
 select id,jsonb_build_object('description',description) into bid,previous from businesses where website=r->>'website' and description=r->>'old' and status='approved' and verified=true;
 if bid is null then raise exception 'Description changed; review %',r->>'name';end if;
 update businesses set description=r->>'next' where id=bid and description=r->>'old';get diagnostics changed=row_count;if changed<>1 then raise exception 'Concurrent description edit';end if;
 applied=jsonb_build_object('description',r->>'next');
 insert into directory_private.listing_corrections(business_id,previous_values,applied_values,reason,source_reference) values(bid,previous,applied,'Use natural searchable service wording; no new service or coverage claim; preserve approval/check dates',r->>'source');
end loop;end $search_copy$;
commit;
